"""Self-contained phone UI; packaged with the Python backend, including Electron."""

PHONE_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="referrer" content="no-referrer"><title>DeepTutor · Phone photos</title>
<style>
:root{color-scheme:light;font:16px system-ui,sans-serif;color:#222;background:#f6f7f9}*{box-sizing:border-box}body{margin:0;padding:24px 16px 40px}main{max-width:520px;margin:auto}h1{font-size:26px;letter-spacing:-.5px;margin:12px 0}p{line-height:1.5;color:#626773}.card{padding:20px;background:white;border:1px solid #e4e6eb;border-radius:18px;margin-top:20px}.actions{display:flex;gap:10px;flex-wrap:wrap}button{font:inherit;border-radius:10px;padding:12px 16px;background:white;border:1px solid #d8dce4;color:#303641;cursor:pointer}button.primary{background:#365fe4;border-color:#365fe4;color:white;flex:1}button:disabled{opacity:.5;cursor:default}ul{list-style:none;padding:0;margin:12px 0}li{display:flex;align-items:center;gap:12px;border-bottom:1px solid #eee;padding:12px 0}li img{width:60px;height:72px;object-fit:cover;border-radius:8px}li div{flex:1;min-width:0}small{display:block;color:#626773;font-size:13px;line-height:1.6}.error{color:#b42318}#status{white-space:pre-line;line-height:1.6}#target{color:#365fe4;word-break:break-word}input[type=file]{display:none}.brand{font-size:13px;font-weight:700;color:#365fe4;letter-spacing:1px}.hint{font-size:13px}
</style></head><body><main><div class="brand">DEEPTUTOR</div><h1 id="heading"></h1><p id="target"></p><p id="intro"></p>
<section class="card"><div class="actions"><button id="camera"></button><button id="album"></button></div>
<input id="cameraInput" type="file" accept="image/*" capture="environment"><input id="albumInput" type="file" accept="image/*" multiple>
<ul id="queue"></ul><button id="upload" class="primary" style="width:100%" disabled></button><p id="status" role="status" aria-live="polite"></p></section>
<p id="receipt" aria-live="polite"></p><p id="expiry" class="hint"></p><p id="notice" class="hint"></p></main>
<script>
'use strict';
const zh=navigator.language.toLowerCase().startsWith('zh');document.documentElement.lang=zh?'zh-CN':'en';
const tr=(a,b)=>zh?a:b,$=id=>document.getElementById(id);
$('heading').textContent=tr('拍照传到电脑','Send photos to your computer');$('intro').textContent=tr('同一页面可以连续上传多批照片。','Keep this page open to send more batches.');
$('camera').textContent=tr('拍照','Take photo');$('album').textContent=tr('从相册选择','Choose photos');$('upload').textContent=tr('上传到对话','Upload to conversation');
$('notice').textContent=tr('照片加入电脑输入框后，由你确认发送。局域网模式使用 HTTP，请在可信网络中使用。','Photos stay in the computer composer until you send them. Local HTTP transfer is intended for trusted networks.');
const key='dt-capture:'+location.host+location.pathname;
let token=location.hash.slice(1);if(token){sessionStorage.setItem(key,token);history.replaceState(null,'',location.pathname);}else{token=sessionStorage.getItem(key)||'';}
const base=location.pathname.replace(/\/$/,'');let files=[],busy=false,info=null,stopped=false;
const id=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const message=(text,error=false)=>{$('status').textContent=text;$('status').className=error?'error':'';};
function render(){
 $('queue').replaceChildren();for(const item of files){const li=document.createElement('li'),img=document.createElement('img'),body=document.createElement('div'),name=document.createElement('span'),state=document.createElement('small');
 img.src=item.url;img.alt='';name.textContent=item.file.name;state.textContent=item.state==='received'?tr('电脑已收到，等待加入输入框','Received; waiting for computer'):item.state==='failed'?tr('失败，可重试','Failed; retry available'):Math.round(item.file.size/1024)+' KB';body.append(name,state);
 const rotate=document.createElement('button');rotate.textContent='↻';rotate.setAttribute('aria-label',tr('旋转照片','Rotate photo'));rotate.disabled=busy||item.state==='received';rotate.onclick=()=>rotatePhoto(item);
 const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',tr('移除照片','Remove photo'));remove.disabled=busy||item.state==='received';remove.onclick=()=>{URL.revokeObjectURL(item.url);files=files.filter(f=>f!==item);render();};
 li.append(img,body,rotate,remove);$('queue').append(li);}
 const blocked=busy||stopped||!info||info.paused;$('camera').disabled=blocked;$('album').disabled=blocked;$('upload').disabled=blocked||!files.some(f=>f.state!=='received');
}
async function rotatePhoto(item){busy=true;render();try{const img=new Image();img.src=item.url;await img.decode();if(img.naturalWidth*img.naturalHeight>40000000)throw Error(tr('图片像素过大','Image is too large'));const scale=Math.min(1,2560/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalHeight*scale);canvas.height=Math.round(img.naturalWidth*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(img,0,0,canvas.height,canvas.width);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error('Image conversion failed');URL.revokeObjectURL(item.url);item.file=new File([blob],'photo.jpg',{type:'image/jpeg'});item.url=URL.createObjectURL(blob);item.id=id();item.state='ready';}catch(e){message(e.message,true);}finally{busy=false;render();}}
function add(picked){if(files.length+picked.length>10){message(tr('每批最多 10 张照片','Choose up to 10 photos per batch'),true);return;}for(const file of picked){if(info&&file.size>info.max_file_bytes){message(tr('照片超过文件大小限制：','Photo exceeds the size limit: ')+file.name,true);continue;}files.push({id:id(),file,url:URL.createObjectURL(file),state:'ready'});}render();}
$('camera').onclick=()=>$('cameraInput').click();$('album').onclick=()=>$('albumInput').click();for(const input of [$('cameraInput'),$('albumInput')])input.onchange=()=>{add(Array.from(input.files));input.value='';};
async function refresh(){if(stopped)return;try{const res=await fetch(base+'/status',{headers:{Authorization:'Bearer '+token},cache:'no-store'});if(res.status===410){stopped=true;message(tr('连接已结束或过期，请在电脑上刷新二维码。','Connection ended or expired. Scan a new QR code.'),true);render();return;}if(!res.ok)throw Error('Connection failed');const wasPaused=Boolean(info&&info.paused);info=await res.json();$('target').textContent=tr('目标对话：','Conversation: ')+info.title;$('expiry').textContent=tr('闲置失效时间：','Idle expiry: ')+new Date(info.expires_at*1000).toLocaleTimeString();$('receipt').textContent=tr('累计已加入电脑输入框：','Added to computer composer: ')+info.files.filter(f=>f.state!=='received').length;const attached=new Set(info.files.filter(f=>f.state!=='received').map(f=>f.client_id));files=files.filter(item=>{if(attached.has(item.id)){URL.revokeObjectURL(item.url);return false;}return true;});if(info.paused)message(tr('电脑已切换对话，返回目标对话后继续。','Return to the target conversation on the computer to continue.'));else if(wasPaused)message(tr('可以继续拍照上传。','Ready to upload more photos.'));render();}catch{if(!busy)message(tr('连接中断，正在重连；已选照片仍保留。','Reconnecting. Your selected photos are kept.'),true);}}
function send(item){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),data=new FormData();data.append('client_file_id',item.id);data.append('file',item.file,item.file.name);xhr.open('POST',base+'/files');xhr.setRequestHeader('Authorization','Bearer '+token);xhr.timeout=120000;xhr.upload.onprogress=e=>{if(e.lengthComputable)message(tr('上传中 ','Uploading ')+Math.round(e.loaded/e.total*100)+'%');};xhr.onload=()=>{let body={};try{body=JSON.parse(xhr.responseText);}catch{}if(xhr.status>=200&&xhr.status<300){item.state='received';resolve();}else reject(Error(body.detail||tr('上传失败，请重试','Upload failed; please retry')));};xhr.onerror=xhr.ontimeout=()=>reject(Error(tr('网络中断，请重试。已接收照片不会重复添加。','Connection interrupted. Retry safely.')));xhr.send(data);});}
$('upload').onclick=async()=>{busy=true;render();let failure=false;for(const item of files.filter(f=>f.state!=='received')){try{await send(item);}catch(e){item.state='failed';message(e.message,true);failure=true;break;}}busy=false;if(!failure)message(tr('电脑已收到。可继续拍照，照片加入输入框后会从队列移除。','Received. Keep taking photos; items clear once added to the composer.'));render();await refresh();};
let timer;function startPolling(){clearInterval(timer);if(!stopped){refresh();timer=setInterval(refresh,2000);}}startPolling();window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('pageshow',startPolling);
</script></body></html>"""
